package main
import ("fmt"; "net/http"; "strconv")
func unidades(n int) string { return []string{"cero","uno","dos","tres","cuatro","cinco","seis","siete","ocho","nueve"}[n] }
func centenas(n int) string { esp:=map[int]string{10:"diez",11:"once",12:"doce",13:"trece",14:"catorce",15:"quince",16:"dieciseis",17:"diecisiete",18:"dieciocho",19:"diecinueve",20:"veinte",21:"veintiuno",22:"veintidos",23:"veintitres",24:"veinticuatro",25:"veinticinco",26:"veintiseis",27:"veintisiete",28:"veintiocho",29:"veintinueve"}; dec:=map[int]string{30:"treinta",40:"cuarenta",50:"cincuenta",60:"sesenta",70:"setenta",80:"ochenta",90:"noventa"}; cie:=map[int]string{100:"cien",200:"doscientos",300:"trescientos",400:"cuatrocientos",500:"quinientos",600:"seiscientos",700:"setecientos",800:"ochocientos",900:"novecientos"}; if n<10{return unidades(n)}; if v,ok:=esp[n];ok{return v}; if n<100{d:=n/10*10;u:=n%10;if u>0{return dec[d]+" y "+unidades(u)};return dec[d]}; if v,ok:=cie[n];ok{return v}; c:=n/100*100;r:=n%100; pref:=cie[c]; if c==100{pref="ciento"}; return pref+" "+centenas(r)}
func numeroALetras(n int) string { if n==0{return "cero"}; if n<0{return "menos "+numeroALetras(-n)}; if n<1000{return centenas(n)}; if n<1000000{m:=n/1000;r:=n%1000; pref:="mil"; if m>1{pref=numeroALetras(m)+" mil"}; if r>0{return pref+" "+centenas(r)}; return pref}; mill:=n/1000000;r:=n%1000000; pref:="un millon"; if mill>1{pref=numeroALetras(mill)+" millones"}; if r>0{return pref+" "+numeroALetras(r)}; return pref }
func main(){ http.HandleFunc("/",func(w http.ResponseWriter,r *http.Request){ n,_:=strconv.Atoi(r.URL.Query().Get("n")); if n==0 && r.URL.Query().Get("n")==""{n=10}; fmt.Fprint(w,numeroALetras(n))}); fmt.Println("Servidor en http://localhost:3000/?n=10"); http.ListenAndServe(":3000",nil)}
